/**
 * Nigeria2023Map.tsx
 * Complete single-file React + TypeScript component
 * Features:
 * - 2023 LGA-level map + 2019/2015 state-level map
 * - APC–PDP margin shown for every state in 2015 & 2019
 * - Working LGA comparison
 * - National dashboard for all three years
 * - Expanded political insights covering 2015–2023
 * - State summary appears first
 * - Better northern spacing
 */

import React, {
  useState,
  useEffect,
  useRef,
  useCallback,
  useMemo,
} from "react";

/* ------------------------------------------------------------------ */
/*  Styles (unchanged)                                                 */
/* ------------------------------------------------------------------ */
const STYLES = `
@import url('https://fonts.googleapis.com/css2?family=Newsreader:opsz,wght@6..72,500;6..72,700&family=Schibsted+Grotesk:wght@400;500;600;700&display=swap');

:root {
  color-scheme: light;
  --paper: #f3f4f1;
  --ink: #101820;
  --muted: #59636e;
  --rule: #d9ddd6;
  --surface: #fff;
}

html, body { background: var(--paper); margin: 0; padding: 0; }
body {
  font-family: 'Schibsted Grotesk', system-ui, -apple-system, 'Segoe UI', sans-serif;
  color: var(--ink);
  padding: env(safe-area-inset-top, 0px) 0 env(safe-area-inset-bottom, 0px);
}
.serif { font-family: 'Newsreader', Georgia, 'Times New Roman', serif; }
.sec-title { font-size: 13px; font-weight: 700; color: var(--ink); margin-bottom: 8px; }

.field {
  width: 100%; background: var(--surface); border: 1px solid var(--rule);
  border-radius: 6px; padding: 8px 10px; font-size: 13px; color: var(--ink);
}
.field:focus-visible, button:focus-visible, input[type=range]:focus-visible,
input[type=checkbox]:focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }

.model-btn {
  width: 100%; text-align: left; padding: 9px 12px 9px 14px;
  border-left: 3px solid transparent; border-radius: 0 6px 6px 0;
  background: transparent; transition: background .12s; cursor: pointer;
}
.model-btn:hover { background: rgba(16,24,32,.045); }
.model-btn.active { background: var(--surface); border-left-color: var(--c); box-shadow: 0 0 0 1px var(--rule); }
.model-btn .t { font-size: 13px; font-weight: 600; }
.model-btn .d { font-size: 12px; color: var(--muted); margin-top: 1px; line-height: 1.35; }

.state-path {
  stroke: #fff; stroke-width: .7;
  transition: fill .55s cubic-bezier(.22,1,.36,1), fill-opacity .55s cubic-bezier(.22,1,.36,1);
}
.state-path:hover { stroke: var(--ink); stroke-width: 1.1; }

.map-btn {
  height: 34px; min-width: 34px; padding: 0 10px; font-size: 13px;
  font-weight: 600; color: var(--ink); background: transparent; border: none; cursor: pointer;
}
.map-btn:hover { background: rgba(16,24,32,.06); }

.visible-arrow {
  transition: stroke .45s cubic-bezier(.22,1,.36,1), stroke-width .25s ease,
              x2 .55s cubic-bezier(.22,1,.36,1), y2 .55s cubic-bezier(.22,1,.36,1);
  will-change: x2, y2, stroke;
}
.lga-vector-group:hover .visible-arrow { stroke-width: 2.6; }

.card {
  background: var(--surface); border: 1px solid var(--rule);
  border-radius: 8px; padding: 12px 14px;
}
.insight-item {
  font-size: 12.5px; line-height: 1.45; padding: 6px 0;
  border-bottom: 1px solid var(--rule);
}
.insight-item:last-child { border-bottom: none; }

.tab-btn {
  padding: 8px 14px; border-radius: 6px; font-size: 13px; font-weight: 600;
  border: 1px solid var(--rule); background: white; cursor: pointer; transition: all .15s;
}
.tab-btn.active { background: var(--ink); color: white; border-color: var(--ink); }

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}
`;

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */
type PartyKey = "apc" | "pdp" | "lp" | "nnpp";
type Model = "incumbent" | "lp_surge" | "duopoly" | "multi_vector";
type Tab = "map" | "dashboard" | "compare" | "insights" | "method";
type Year = 2023 | 2019 | 2015;

interface Votes { apc: number; lp: number; pdp: number; nnpp: number; total: number; }
interface Results2023 { apc: number; pdp: number; lp: number; nnpp: number; }
interface Lga {
  id: string; state: string; lgaName: string;
  cx: number; cy: number;
  votes: Votes; results2023: Results2023;
}
interface Vector {
  angle: number; length: number; color: string; markerId: string;
  shiftPp: number; narrative: string;
}
interface StateResult {
  pdp: number; apc: number; nnpp: number; lp: number; other: number;
  winner: "pdp" | "apc";
}

