/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */
const PARTY: Record<PartyKey, [string, string, string]> = {
  apc: ["APC", "#2563eb", "arrow-apc"],
  pdp: ["PDP", "#dc2626", "arrow-pdp"],
  lp: ["LP", "#16a34a", "arrow-lp"],
  nnpp: ["NNPP", "#9333ea", "arrow-nnpp"],
};

const NORTHERN = new Set([
  "Sokoto", "Zamfara", "Katsina", "Kano", "Jigawa", "Yobe", "Borno",
  "Bauchi", "Gombe", "Adamawa", "Taraba", "Kaduna", "Kebbi", "Niger",
  "Kwara", "Kogi", "Nasarawa", "Plateau", "FCT Abuja"
]);

function computeShiftVector(lga: Lga, model: Model, scaleFactor: number): Vector {
  const r = lga.results2023;
  const ranked = (Object.keys(PARTY) as PartyKey[]).sort((a, b) => r[b] - r[a]);
  const win = ranked[0];
  const second = ranked[1];
  const pct = (x: number) => (x * 100).toFixed(1);

  let shiftPp = 0, angle = 0, color = "#2563eb", markerId = "arrow-apc", narrative = "";

  if (model === "incumbent") {
    const bestOpp = ranked.find(k => k !== "apc")!;
    shiftPp = (r.apc - r[bestOpp]) * 100;
    if (shiftPp >= 0) {
      angle = -Math.PI / 4;
      narrative = `APC led with ${pct(r.apc)}% (${pct(r.apc - r[bestOpp])} pts ahead of ${PARTY[bestOpp][0]}).`;
    } else {
      angle = 3 * Math.PI / 4; color = "#ea580c"; markerId = "arrow-neutral";
      narrative = `${PARTY[bestOpp][0]} led with ${pct(r[bestOpp])}% (${pct(r[bestOpp] - r.apc)} pts ahead of APC).`;
    }
  } else if (model === "lp_surge") {
    shiftPp = r.lp * 100; angle = -Math.PI / 2; color = "#16a34a"; markerId = "arrow-lp";
    narrative = `LP took ${pct(r.lp)}%${win === "lp" ? " and led" : ""}.`;
  } else if (model === "duopoly") {
    shiftPp = (r.apc - r.pdp) * 100;
    if (shiftPp >= 0) { angle = -Math.PI / 4; narrative = `APC beat PDP by ${pct(r.apc - r.pdp)} pts.`; }
    else { angle = 3 * Math.PI / 4; color = "#dc2626"; markerId = "arrow-pdp"; narrative = `PDP beat APC by ${pct(r.pdp - r.apc)} pts.`; }
  } else {
    const vx = r.apc * Math.cos(-Math.PI / 4) + r.pdp * Math.cos(-3 * Math.PI / 4) + r.nnpp;
    const vy = r.apc * Math.sin(-Math.PI / 4) + r.pdp * Math.sin(-3 * Math.PI / 4) + r.lp;
    shiftPp = Math.sqrt(vx * vx + vy * vy) * 100;
    angle = Math.atan2(vy, vx);
    color = PARTY[win][1]; markerId = PARTY[win][2];
    narrative = `${PARTY[win][0]} led with ${pct(r[win])}% (${pct(r[win] - r[second])} pts ahead of ${PARTY[second][0]}).`;
  }

  const len = Math.min(26, Math.max(4, Math.abs(shiftPp) * 0.38 * scaleFactor));
  return { angle, length: len, color, markerId, shiftPp, narrative };
}

function getStateResult(year: Year, state: string): StateResult | null {
  if (year === 2015) return STATE_RESULTS_2015[state] || null;
  if (year === 2019) return STATE_RESULTS_2019[state] || null;
  return null;
}

/* ------------------------------------------------------------------ */
/*  Main Component                                                     */
/* ------------------------------------------------------------------ */
export default function Nigeria2023Map() {
  const [year, setYear] = useState<Year>(2023);
  const [currentModel, setCurrentModel] = useState<Model>("incumbent");
  const [currentScale, setCurrentScale] = useState(1.0);
  const [selectedLga, setSelectedLga] = useState<{ lga: Lga; vec: Vector } | null>(null);
  const [compareA, setCompareA] = useState<Lga | null>(null);
  const [compareB, setCompareB] = useState<Lga | null>(null);
  const [zoomLevel, setZoomLevel] = useState(1);
  const [panX, setPanX] = useState(0);
  const [panY, setPanY] = useState(0);
  const [showLabels, setShowLabels] = useState(true);
  const [stateFilter, setStateFilter] = useState("ALL");
  const [searchQuery, setSearchQuery] = useState("");
  const [activeTab, setActiveTab] = useState<Tab>("map");
  const [tooltip, setTooltip] = useState<{
    visible: boolean; x: number; y: number; lga: Lga | null; vec: Vector | null;
  }>({ visible: false, x: 0, y: 0, lga: null, vec: null });

  const svgRef = useRef<SVGSVGElement>(null);
  const viewportRef = useRef<SVGGElement>(null);
  const [lgaData, setLgaData] = useState<Lga[]>([]);

  useEffect(() => {
    const data: Lga[] = [];
    Object.keys(STATE_BOUNDS).forEach(stateName => {
      const info = STATE_BOUNDS[stateName];
      (LGA_RESULTS[stateName] || []).forEach((row, idx) => {
        const [name, apc, lp, pdp, nnpp] = row;
        const tot = apc + lp + pdp + nnpp || 1;
        const angle = (idx / (info.lgas || 1)) * Math.PI * 2;
        const radius = NORTHERN.has(stateName)
          ? 12 + (idx % 6) * 4.2
          : 8 + (idx % 5) * 3;
        data.push({
          id: `${stateName}_${idx + 1}`,
          state: stateName,
          lgaName: name,
          cx: Math.round((info.cx + Math.cos(angle) * radius) * 10) / 10,
          cy: Math.round((info.cy + Math.sin(angle) * radius) * 10) / 10,
          votes: { apc, lp, pdp, nnpp, total: tot },
          results2023: { apc: apc / tot, pdp: pdp / tot, lp: lp / tot, nnpp: nnpp / tot },
        });
      });
    });
    setLgaData(data);
  }, []);

  useEffect(() => {
    if (viewportRef.current) {
      viewportRef.current.style.transition = "transform 0.45s cubic-bezier(0.22, 1, 0.36, 1)";
      viewportRef.current.setAttribute("transform", `translate(${panX}, ${panY}) scale(${zoomLevel})`);
    }
  }, [panX, panY, zoomLevel]);

  const resetView = useCallback(() => {
    setZoomLevel(1); setPanX(0); setPanY(0); setStateFilter("ALL"); setSearchQuery("");
  }, []);

  const zoomToState = useCallback((stateName: string) => {
    const info = STATE_BOUNDS[stateName];
    if (!info) return;
    const targetZoom = 2.4;
    setZoomLevel(targetZoom);
    setPanX(370 - info.cx * targetZoom);
    setPanY(300 - info.cy * targetZoom);
    setStateFilter(stateName);
  }, []);

  /* ---------- National aggregates (year-aware) ---------- */
  const national = useMemo(() => {
    if (year === 2023) {
      const totals = { apc: 0, lp: 0, pdp: 0, nnpp: 0, total: 0 };
      const won = { apc: 0, lp: 0, pdp: 0, nnpp: 0 };
      lgaData.forEach(l => {
        totals.apc += l.votes.apc; totals.lp += l.votes.lp;
        totals.pdp += l.votes.pdp; totals.nnpp += l.votes.nnpp;
        totals.total += l.votes.total;
        const winner = (Object.keys(won) as PartyKey[]).sort((a, b) => l.votes[b] - l.votes[a])[0];
        won[winner]++;
      });
      return { totals, won, totalUnits: lgaData.length, unit: "LGAs" };
    }

    const source = year === 2015 ? STATE_RESULTS_2015 : STATE_RESULTS_2019;
    const totals = { apc: 0, lp: 0, pdp: 0, nnpp: 0, total: 0 };
    const won = { apc: 0, lp: 0, pdp: 0, nnpp: 0 };
    Object.values(source).forEach(r => {
      totals.apc += r.apc; totals.pdp += r.pdp;
      totals.lp += r.lp; totals.nnpp += r.nnpp;
      totals.total += r.apc + r.pdp + r.lp + r.nnpp + r.other;
      won[r.winner]++;
    });
    return { totals, won, totalUnits: 37, unit: "states" };
  }, [lgaData, year]);

  /* ---------- State summary ---------- */
  const stateSummary = useMemo(() => {
    if (stateFilter === "ALL") return null;
    if (year === 2023) {
      const subset = lgaData.filter(l => l.state === stateFilter);
      const totals = { apc: 0, lp: 0, pdp: 0, nnpp: 0, total: 0 };
      const won = { apc: 0, lp: 0, pdp: 0, nnpp: 0 };
      subset.forEach(l => {
        totals.apc += l.votes.apc; totals.lp += l.votes.lp;
        totals.pdp += l.votes.pdp; totals.nnpp += l.votes.nnpp;
        totals.total += l.votes.total;
        const winner = (Object.keys(won) as PartyKey[]).sort((a, b) => l.votes[b] - l.votes[a])[0];
        won[winner]++;
      });
      return { totals, won, units: subset.length, unitLabel: "LGAs" };
    }
    const res = getStateResult(year, stateFilter);
    if (!res) return null;
    const total = res.apc + res.pdp + res.lp + res.nnpp + res.other;
    return {
      totals: { apc: res.apc, pdp: res.pdp, lp: res.lp, nnpp: res.nnpp, total },
      won: { apc: res.winner === "apc" ? 1 : 0, pdp: res.winner === "pdp" ? 1 : 0, lp: 0, nnpp: 0 },
      units: 1,
      unitLabel: "state",
    };
  }, [lgaData, stateFilter, year]);

  /* ---------- Expanded Political Insights (2015–2023) ---------- */
  const insights = useMemo(() => {
    const items: { title: string; items: string[] }[] = [];

    // 2023 LGA insights
    if (lgaData.length > 0) {
      const byMargin = lgaData.map(l => {
        const ranked = (Object.keys(PARTY) as PartyKey[]).sort((a, b) => l.votes[b] - l.votes[a]);
        const margin = ((l.votes[ranked[0]] - l.votes[ranked[1]]) / l.votes.total) * 100;
        return { lga: l, winner: ranked[0], margin };
      });
      const closest = [...byMargin].sort((a, b) => a.margin - b.margin).slice(0, 5);
      const widest = [...byMargin].sort((a, b) => b.margin - a.margin).slice(0, 5);
      const lpStrong = lgaData.filter(l => l.results2023.lp > 0.45)
        .sort((a, b) => b.results2023.lp - a.results2023.lp).slice(0, 5);

      items.push(
        {
          title: "Closest LGA contests (2023)", items: closest.map(c =>
            `${c.lga.lgaName} (${c.lga.state}) – ${PARTY[c.winner][0]} by only ${c.margin.toFixed(1)} pts`)
        },
        {
          title: "Widest LGA margins (2023)", items: widest.map(c =>
            `${c.lga.lgaName} (${c.lga.state}) – ${PARTY[c.winner][0]} by ${c.margin.toFixed(1)} pts`)
        },
        {
          title: "Deep LP strongholds (>45%)", items: lpStrong.map(l =>
            `${l.lgaName} (${l.state}) – ${(l.results2023.lp * 100).toFixed(1)}%`)
        }
      );
    }

    // Historical flips & swings
    const flips1519: string[] = [];
    const flips1923: string[] = [];
    const bigSwings: string[] = [];

    Object.keys(STATE_BOUNDS).forEach(state => {
      const r15 = STATE_RESULTS_2015[state];
      const r19 = STATE_RESULTS_2019[state];
      if (r15 && r19 && r15.winner !== r19.winner) {
        flips1519.push(`${state}: ${r15.winner.toUpperCase()} → ${r19.winner.toUpperCase()}`);
      }
      // 2023 state winner from LGA aggregation
      const subset = lgaData.filter(l => l.state === state);
      if (subset.length) {
        const tot = { apc: 0, pdp: 0, lp: 0, nnpp: 0 };
        subset.forEach(l => { tot.apc += l.votes.apc; tot.pdp += l.votes.pdp; tot.lp += l.votes.lp; tot.nnpp += l.votes.nnpp; });
        const winner23 = (Object.keys(tot) as PartyKey[]).sort((a, b) => tot[b] - tot[a])[0];
        if (r19 && r19.winner !== winner23 && (winner23 === "apc" || winner23 === "pdp")) {
          flips1923.push(`${state}: ${r19.winner.toUpperCase()} → ${winner23.toUpperCase()}`);
        }
        if (r19) {
          const margin19 = ((r19.apc - r19.pdp) / (r19.apc + r19.pdp || 1)) * 100;
          const margin23 = ((tot.apc - tot.pdp) / (tot.apc + tot.pdp || 1)) * 100;
          const swing = margin23 - margin19;
          if (Math.abs(swing) > 15) {
            bigSwings.push(`${state}: ${swing > 0 ? "+" : ""}${swing.toFixed(1)} pts APC swing`);
          }
        }
      }
    });

    if (flips1519.length) items.push({ title: "States that flipped 2015 → 2019", items: flips1519 });
    if (flips1923.length) items.push({ title: "States that flipped 2019 → 2023", items: flips1923 });
    if (bigSwings.length) items.push({ title: "Largest APC–PDP swings (2019→2023)", items: bigSwings.slice(0, 8) });

    // Structural observations
    items.push({
      title: "Structural patterns",
      items: [
        "The South-East remained the only zone where a third force (LP) displaced the traditional duopoly in 2023.",
        "Northern states with the highest 2015 APC margins largely held or expanded those margins in 2019.",
        "Several South-West states that were comfortable APC wins in 2015 became much closer in 2019 and 2023.",
        "The FCT has consistently been competitive and has never produced a landslide for either major party.",
      ]
    });

    return items;
  }, [lgaData]);

  const inspectLga = useCallback((lga: Lga, vec: Vector, e: React.MouseEvent) => {
    setTooltip({ visible: true, x: e.clientX, y: e.clientY, lga, vec });
  }, []);
  const pinLga = useCallback((lga: Lga, vec: Vector) => setSelectedLga({ lga, vec }), []);
  const hideTooltip = useCallback(() => setTooltip(t => ({ ...t, visible: false })), []);

  const models = [
    { id: "incumbent" as Model, label: "Did the ruling party lead?", desc: "Blue = APC led, orange = opposition led", color: "#2563eb" },
    { id: "lp_surge" as Model, label: "Labour Party’s share", desc: "How much of the vote Peter Obi’s party took", color: "#16a34a" },
    { id: "duopoly" as Model, label: "APC against PDP", desc: "Margin between the two longtime rivals", color: "#dc2626" },
    { id: "multi_vector" as Model, label: "All four parties", desc: "Net direction across APC, PDP, LP & NNPP", color: "#101820" },
  ];

  return (
    <>
      <style>{STYLES}</style>

      <div className="max-w-[1400px] mx-auto px-3 sm:px-6 pt-5 sm:pt-8 pb-6">
        <header className="pb-5 border-b border-[color:var(--rule)]">
          <h1 className="serif text-[34px] sm:text-5xl leading-[1.05] font-bold tracking-tight">
            nivo – How Nigeria voted
          </h1>
          <p className="mt-2.5 text-[15px] leading-relaxed text-[color:var(--muted)] max-w-[70ch]">
            Explore the 2023, 2019 and 2015 presidential results. Each arrow is one local government area (2023) or one state (earlier years).
          </p>

          <div className="mt-4 flex flex-wrap gap-2">
            {([
              { id: "map", label: "Map" },
              { id: "dashboard", label: "National dashboard" },
              { id: "compare", label: "LGA comparison" },
              { id: "insights", label: "Political insights" },
              { id: "method", label: "Methodology" },
            ] as const).map(tab => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`tab-btn ${activeTab === tab.id ? "active" : ""}`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </header>

        {/* Year selector */}
        {(activeTab === "map" || activeTab === "dashboard") && (
          <div className="mt-4 flex items-center gap-3">
            <span className="text-sm font-semibold">Year:</span>
            {[2023, 2019, 2015].map(y => (
              <button
                key={y}
                onClick={() => setYear(y as Year)}
                className={`tab-btn ${year === y ? "active" : ""}`}
              >
                {y}
              </button>
            ))}
          </div>
        )}

        {/* ========== NATIONAL DASHBOARD ========== */}
        {activeTab === "dashboard" && (
          <div className="mt-6 grid gap-4 md:grid-cols-2 lg:grid-cols-4">
            {(Object.keys(PARTY) as PartyKey[]).map(k => {
              const share = national.totals.total ? (national.totals[k] / national.totals.total * 100) : 0;
              return (
                <div key={k} className="card">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="w-3 h-3 rounded-sm" style={{ background: PARTY[k][1] }} />
                    <span className="font-bold">{PARTY[k][0]}</span>
                  </div>
                  <div className="text-2xl font-bold tabular-nums">{national.totals[k].toLocaleString()}</div>
                  <div className="text-sm text-[color:var(--muted)]">{share.toFixed(1)}% of total</div>
                  <div className="mt-2 text-sm">
                    Led in <strong>{national.won[k]}</strong> {national.unit}
                  </div>
                </div>
              );
            })}
            <div className="card md:col-span-2 lg:col-span-4">
              <h3 className="sec-title">{year} – Units won</h3>
              <div className="flex h-4 gap-[2px] overflow-hidden rounded-sm bg-white mt-2">
                {(Object.keys(PARTY) as PartyKey[]).map(k => (
                  <div key={k} style={{ flex: national.won[k] || 0.01, background: PARTY[k][1] }}
                    title={`${PARTY[k][0]}: ${national.won[k]}`} />
                ))}
              </div>
            </div>
          </div>
        )}

        {/* ========== LGA COMPARISON (fully working) ========== */}
        {activeTab === "compare" && (
          <div className="mt-6">
            {year !== 2023 ? (
              <div className="card text-[color:var(--muted)]">
                LGA-level comparison is only available for 2023. Switch to the 2023 year on the Map or Dashboard tab.
              </div>
            ) : (
              <div className="grid gap-6 lg:grid-cols-2">
                <div className="space-y-3">
                  <h3 className="sec-title">Select first LGA</h3>
                  <select
                    className="field"
                    value={compareA?.id || ""}
                    onChange={e => setCompareA(lgaData.find(l => l.id === e.target.value) || null)}
                  >
                    <option value="">— choose —</option>
                    {lgaData.map(l => (
                      <option key={l.id} value={l.id}>{l.lgaName} ({l.state})</option>
                    ))}
                  </select>
                </div>
                <div className="space-y-3">
                  <h3 className="sec-title">Select second LGA</h3>
                  <select
                    className="field"
                    value={compareB?.id || ""}
                    onChange={e => setCompareB(lgaData.find(l => l.id === e.target.value) || null)}
                  >
                    <option value="">— choose —</option>
                    {lgaData.map(l => (
                      <option key={l.id} value={l.id}>{l.lgaName} ({l.state})</option>
                    ))}
                  </select>
                </div>

                {compareA && compareB && (
                  <div className="lg:col-span-2 card">
                    <h3 className="sec-title mb-3">Side-by-side comparison</h3>
                    <div className="overflow-x-auto">
                      <table className="w-full text-sm">
                        <thead>
                          <tr className="border-b border-[color:var(--rule)]">
                            <th className="text-left py-2">Metric</th>
                            <th className="text-right py-2">{compareA.lgaName}</th>
                            <th className="text-right py-2">{compareB.lgaName}</th>
                          </tr>
                        </thead>
                        <tbody>
                          {(Object.keys(PARTY) as PartyKey[]).map(k => (
                            <tr key={k} className="border-b border-[color:var(--rule)]">
                              <td className="py-2 font-medium">{PARTY[k][0]} votes</td>
                              <td className="text-right tabular-nums">{compareA.votes[k].toLocaleString()}</td>
                              <td className="text-right tabular-nums">{compareB.votes[k].toLocaleString()}</td>
                            </tr>
                          ))}
                          <tr className="border-b border-[color:var(--rule)]">
                            <td className="py-2 font-medium">Total (four parties)</td>
                            <td className="text-right tabular-nums">{compareA.votes.total.toLocaleString()}</td>
                            <td className="text-right tabular-nums">{compareB.votes.total.toLocaleString()}</td>
                          </tr>
                          <tr>
                            <td className="py-2 font-medium">Winning margin (pp)</td>
                            <td className="text-right">
                              {(() => {
                                const ranked = (Object.keys(PARTY) as PartyKey[]).sort((a, b) => compareA.votes[b] - compareA.votes[a]);
                                return ((compareA.votes[ranked[0]] - compareA.votes[ranked[1]]) / compareA.votes.total * 100).toFixed(1);
                              })()}
                            </td>
                            <td className="text-right">
                              {(() => {
                                const ranked = (Object.keys(PARTY) as PartyKey[]).sort((a, b) => compareB.votes[b] - compareB.votes[a]);
                                return ((compareB.votes[ranked[0]] - compareB.votes[ranked[1]]) / compareB.votes.total * 100).toFixed(1);
                              })()}
                            </td>
                          </tr>
                        </tbody>
                      </table>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* ========== POLITICAL INSIGHTS ========== */}
        {activeTab === "insights" && (
          <div className="mt-6 grid gap-4 md:grid-cols-2">
            {insights.map(block => (
              <div key={block.title} className="card">
                <h3 className="sec-title">{block.title}</h3>
                {block.items.map((item, i) => (
                  <div key={i} className="insight-item">{item}</div>
                ))}
              </div>
            ))}
          </div>
        )}

        {/* ========== METHODOLOGY ========== */}
        {activeTab === "method" && (
          <div className="mt-6 max-w-3xl space-y-4 text-[15px] leading-relaxed">
            <div className="card">
              <h3 className="sec-title">Dataset</h3>
              <p>2023 LGA results from the public anndawn/Nigeria-2023-election dataset. 2015 and 2019 figures are official INEC state-level collated results.</p>
            </div>
            <div className="card">
              <h3 className="sec-title">Calculations</h3>
              <ul className="list-disc pl-5 space-y-1">
                <li>Share = party votes ÷ (APC + PDP + LP + NNPP).</li>
                <li>Margin = difference between first and second place as percentage points of the four-party total.</li>
                <li>Arrow length is proportional to the absolute margin (or LP share), scaled by the user control.</li>
              </ul>
            </div>
            <div className="card">
              <h3 className="sec-title">Limitations</h3>
              <ul className="list-disc pl-5 space-y-1">
                <li>LGA boundaries are not drawn; arrow positions are approximate.</li>
                <li>Only presidential results are shown.</li>
                <li>2015 and 2019 data are available only at state level.</li>
              </ul>
            </div>
          </div>
        )}

        {/* ========== MAP VIEW ========== */}
        {activeTab === "map" && (
          <div className="grid grid-cols-1 lg:grid-cols-[340px_1fr] mt-4">
            <aside className="order-2 lg:order-1 lg:pr-6 py-5 flex flex-col gap-6 lg:border-r border-[color:var(--rule)]">
              {/* STATE SUMMARY FIRST */}
              {stateFilter !== "ALL" && stateSummary && (
                <section className="card border-2 border-[color:var(--ink)]">
                  <h2 className="sec-title text-base">{stateFilter} · {year}</h2>
                  <div className="text-xs space-y-1 mt-2">
                    {(Object.keys(PARTY) as PartyKey[]).map(k => (
                      <div key={k} className="flex justify-between">
                        <span className="flex items-center gap-1.5">
                          <span className="w-2 h-2 rounded-sm" style={{ background: PARTY[k][1] }} />
                          {PARTY[k][0]}
                        </span>
                        <span className="tabular-nums">{stateSummary.totals[k].toLocaleString()}</span>
                      </div>
                    ))}
                  </div>
                  {year !== 2023 && (
                    <p className="mt-2 text-xs text-[color:var(--muted)]">
                      APC–PDP margin:{" "}
                      {(() => {
                        const t = stateSummary.totals;
                        const m = ((t.apc - t.pdp) / (t.apc + t.pdp || 1) * 100);
                        return `${m >= 0 ? "+" : ""}${m.toFixed(1)} pts`;
                      })()}
                    </p>
                  )}
                </section>
              )}
              {/* Find a place */}
              <section>
                <div className="flex items-center justify-between">
                  <h2 className="sec-title">Find a place</h2>
                  {stateFilter !== "ALL" && (
                    <button onClick={resetView} className="text-xs font-semibold underline underline-offset-2 mb-2">
                      Back to national view
                    </button>
                  )}
                </div>
                <div className="space-y-2">
                  <select
                    className="field"
                    value={stateFilter}
                    onChange={e => {
                      const v = e.target.value;
                      if (v === "ALL") resetView(); else zoomToState(v);
                    }}
                  >
                    <option value="ALL">All of Nigeria</option>
                    {Object.keys(STATE_BOUNDS).sort().map(st => (
                      <option key={st} value={st}>{st} ({STATE_BOUNDS[st].lgas} LGAs)</option>
                    ))}
                  </select>
                  {year === 2023 && (
                    <input
                      type="text"
                      className="field"
                      placeholder="Search an LGA…"
                      value={searchQuery}
                      onChange={e => {
                        const q = e.target.value.toLowerCase().trim();
                        setSearchQuery(e.target.value);
                        if (!q) return;
                        const found = lgaData.find(l =>
                          l.lgaName.toLowerCase().includes(q) || l.state.toLowerCase().includes(q)
                        );
                        if (found) {
                          zoomToState(found.state);
                          const vec = computeShiftVector(found, currentModel, currentScale);
                          pinLga(found, vec);
                        }
                      }}
                    />
                  )}
                </div>
              </section>

              {/* Models (2023 only) */}
              {year === 2023 && (
                <section>
                  <h2 className="sec-title">What to show</h2>
                  <div className="space-y-1">
                    {models.map(m => (
                      <button
                        key={m.id}
                        style={{ "--c": m.color } as React.CSSProperties}
                        className={`model-btn ${currentModel === m.id ? "active" : ""}`}
                        onClick={() => setCurrentModel(m.id)}
                      >
                        <div className="t">{m.label}</div>
                        <div className="d">{m.desc}</div>
                      </button>
                    ))}
                  </div>
                </section>
              )}

              {/* Legend */}
              <section className="card">
                <h2 className="sec-title">Map legend</h2>
                <div className="space-y-2 text-xs">
                  <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
                    <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-sm bg-[#2563eb]" /> APC</span>
                    <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-sm bg-[#dc2626]" /> PDP</span>
                    <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-sm bg-[#16a34a]" /> LP</span>
                    <span className="flex items-center gap-1"><span className="w-3 h-3 rounded-sm bg-[#9333ea]" /> NNPP</span>
                  </div>
                  <p className="text-[color:var(--muted)] leading-relaxed">
                    {year === 2023
                      ? "Arrow colour = leading party. Length ∝ size of the lead."
                      : "Arrow colour and length show the APC–PDP margin for each state."}
                  </p>
                </div>
              </section>

              {/* Pinned LGA */}
              <section className="rounded-lg bg-[color:var(--ink)] text-white p-4 space-y-2.5">
                <div className="flex items-start justify-between gap-3 border-b border-white/15 pb-2.5">
                  <div className="min-w-0">
                    <div className="text-xs text-white/60">Selected area</div>
                    <h3 className="serif text-xl font-bold leading-tight break-words">
                      {selectedLga ? selectedLga.lga.lgaName : "Pick an LGA"}
                    </h3>
                  </div>
                  <span className="shrink-0 text-xs font-semibold text-white/70 pt-4">
                    {selectedLga ? selectedLga.lga.state : "Nigeria"}
                  </span>
                </div>
                {selectedLga ? (
                  <div className="space-y-2 text-xs">
                    <p className="text-white/90 text-[13px] leading-relaxed">{selectedLga.vec.narrative}</p>
                    <div className="grid grid-cols-2 gap-2 text-center pt-1">
                      <div className="bg-slate-800/80 p-2 rounded border border-slate-700">
                        <div className="text-[10px] text-slate-400 uppercase font-bold">Votes</div>
                        <div className="text-[11px] font-bold text-slate-200 leading-snug">
                          APC {selectedLga.lga.votes.apc.toLocaleString()}<br />
                          LP {selectedLga.lga.votes.lp.toLocaleString()}<br />
                          PDP {selectedLga.lga.votes.pdp.toLocaleString()}<br />
                          NNPP {selectedLga.lga.votes.nnpp.toLocaleString()}
                        </div>
                      </div>
                      <div className="bg-slate-800/80 p-2 rounded border border-slate-700">
                        <div className="text-[10px] text-slate-400 uppercase font-bold">Margin</div>
                        <div className="text-xs font-bold text-emerald-400">
                          {selectedLga.vec.shiftPp >= 0 ? "+" : ""}{selectedLga.vec.shiftPp.toFixed(1)} pp
                        </div>
                      </div>
                    </div>
                  </div>
                ) : (
                  <p className="text-white/70 text-[13px] leading-relaxed">
                    Click an arrow or search for an LGA to see its vote counts, winner and margin.
                  </p>
                )}
              </section>

              {/* Controls */}
              <section className="space-y-3 text-[13px]">
                <div>
                  <div className="flex justify-between mb-1.5">
                    <label className="font-semibold">Arrow length</label>
                    <span className="font-semibold tabular-nums">{currentScale.toFixed(1)}x</span>
                  </div>
                  <input
                    type="range" min="0.4" max="2.0" step="0.1" value={currentScale}
                    onChange={e => setCurrentScale(parseFloat(e.target.value))}
                    className="w-full accent-[color:var(--ink)] cursor-pointer"
                  />
                </div>
                <label className="flex items-center justify-between cursor-pointer">
                  <span className="font-semibold">Show state names</span>
                  <input
                    type="checkbox" checked={showLabels}
                    onChange={e => setShowLabels(e.target.checked)}
                    className="w-4 h-4 accent-[color:var(--ink)] cursor-pointer"
                  />
                </label>
              </section>
            </aside>

            {/* Map */}
            <main className="order-1 lg:order-2 relative flex flex-col h-[72vh] min-h-[460px] lg:h-screen lg:max-h-[920px] lg:sticky lg:top-0 lg:self-start">
              <div className="absolute top-3 left-3 lg:left-6 z-10 flex items-center rounded-md bg-white border border-[color:var(--rule)] overflow-hidden">
                <button className="map-btn" onClick={() => setZoomLevel(z => Math.min(4.5, z + 0.35))}>+</button>
                <button className="map-btn border-l border-[color:var(--rule)]" onClick={() => setZoomLevel(z => Math.max(0.7, z - 0.35))}>−</button>
                <button className="map-btn border-l border-[color:var(--rule)]" onClick={resetView}>Reset</button>
              </div>

              <div className="flex-1 relative min-h-[460px] overflow-hidden">
                <svg
                  ref={svgRef}
                  viewBox="0 0 744.24182 599.92847"
                  className="absolute inset-0 w-full h-full cursor-crosshair select-none"
                  onMouseLeave={hideTooltip}
                >
                  <defs>
                    <marker id="arrow-apc" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="4.5" markerHeight="4.5" orient="auto-start-reverse">
                      <path d="M 0 1.5 L 8 5 L 0 8.5 z" fill="#2563eb" />
                    </marker>
                    <marker id="arrow-pdp" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="4.5" markerHeight="4.5" orient="auto-start-reverse">
                      <path d="M 0 1.5 L 8 5 L 0 8.5 z" fill="#dc2626" />
                    </marker>
                    <marker id="arrow-lp" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="4.5" markerHeight="4.5" orient="auto-start-reverse">
                      <path d="M 0 1.5 L 8 5 L 0 8.5 z" fill="#16a34a" />
                    </marker>
                    <marker id="arrow-nnpp" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="4.5" markerHeight="4.5" orient="auto-start-reverse">
                      <path d="M 0 1.5 L 8 5 L 0 8.5 z" fill="#9333ea" />
                    </marker>
                    <marker id="arrow-neutral" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="4.5" markerHeight="4.5" orient="auto-start-reverse">
                      <path d="M 0 1.5 L 8 5 L 0 8.5 z" fill="#ea580c" />
                    </marker>
                  </defs>

                  <g ref={viewportRef}>
                    <g>
                      {Object.entries(STATE_BOUNDS).map(([name, info]) => (
                        <path
                          key={name}
                          d={STATE_PATHS[info.id] || ""}
                          fill="#e5e7e2"
                          strokeLinejoin="round"
                          className="state-path cursor-pointer"
                          onClick={() => zoomToState(name)}
                        />
                      ))}
                    </g>

                    <g className="pointer-events-none select-none" style={{ opacity: showLabels ? 1 : 0 }}>
                      {Object.entries(STATE_BOUNDS).map(([name, info]) => (
                        <text
                          key={name}
                          x={info.cx}
                          y={info.cy - 8}
                          fontSize={name.length > 10 ? 6 : 7.5}
                          fontWeight="700"
                          fill="#2b3540"
                          textAnchor="middle"
                          paintOrder="stroke"
                          stroke="#ffffff"
                          strokeWidth="2.2"
                          strokeOpacity="0.85"
                        >
                          {name === "FCT Abuja" ? "FCT" : name}
                        </text>
                      ))}
                    </g>

                    <g>
                      {year === 2023
                        ? lgaData.map(lga => {
                          const vec = computeShiftVector(lga, currentModel, currentScale);
                          const dx = Math.cos(vec.angle) * vec.length;
                          const dy = Math.sin(vec.angle) * vec.length;
                          return (
                            <g
                              key={lga.id}
                              className="lga-vector-group cursor-pointer"
                              onMouseEnter={e => inspectLga(lga, vec, e)}
                              onClick={() => pinLga(lga, vec)}
                            >
                              <circle cx={lga.cx} cy={lga.cy} r="1.1" fill="#101820" opacity="0.28" />
                              <line x1={lga.cx} y1={lga.cy} x2={lga.cx + dx} y2={lga.cy + dy}
                                stroke="transparent" strokeWidth="16" strokeLinecap="round" />
                              <line
                                className="visible-arrow"
                                x1={lga.cx} y1={lga.cy}
                                x2={lga.cx + dx} y2={lga.cy + dy}
                                stroke={vec.color} strokeWidth="1.6" strokeLinecap="round"
                                markerEnd={`url(#${vec.markerId})`}
                              />
                            </g>
                          );
                        })
                        : Object.entries(STATE_BOUNDS).map(([name, info]) => {
                          const res = getStateResult(year, name);
                          if (!res) return null;
                          const total = res.apc + res.pdp || 1;
                          const margin = ((res.apc - res.pdp) / total) * 100;
                          const color = margin >= 0 ? "#2563eb" : "#dc2626";
                          const marker = margin >= 0 ? "arrow-apc" : "arrow-pdp";
                          const angle = margin >= 0 ? -Math.PI / 4 : 3 * Math.PI / 4;
                          const len = Math.min(28, Math.max(8, Math.abs(margin) * 0.35 * currentScale));
                          const dx = Math.cos(angle) * len;
                          const dy = Math.sin(angle) * len;
                          return (
                            <g key={name} className="lga-vector-group cursor-pointer"
                              onClick={() => zoomToState(name)}>
                              <circle cx={info.cx} cy={info.cy} r="2" fill="#101820" opacity="0.3" />
                              <line
                                className="visible-arrow"
                                x1={info.cx} y1={info.cy}
                                x2={info.cx + dx} y2={info.cy + dy}
                                stroke={color} strokeWidth="2.2" strokeLinecap="round"
                                markerEnd={`url(#${marker})`}
                              />
                            </g>
                          );
                        })}
                    </g>
                  </g>
                </svg>
              </div>

              <p className="px-3 lg:pl-6 py-3 text-xs leading-relaxed text-[color:var(--muted)] border-t border-[color:var(--rule)] max-w-[100ch]">
                {year === 2023
                  ? "Each arrow is one of Nigeria’s 774 LGAs. Longer arrows mean wider leads."
                  : `State-level results for the ${year} presidential election. One arrow per state showing the APC–PDP margin.`}
              </p>
            </main>
          </div>
        )}
      </div>

      {/* Tooltip */}
      {tooltip.visible && tooltip.lga && tooltip.vec && (
        <div
          className="fixed z-50 bg-[color:var(--ink)] text-white px-4 py-3 rounded-lg shadow-xl text-xs w-[280px] pointer-events-none -translate-x-1/2 -translate-y-full -mt-3"
          style={{ left: tooltip.x, top: tooltip.y }}
        >
          <div className="flex items-baseline justify-between gap-3 border-b border-white/15 pb-1.5 mb-2">
            <span className="serif text-base font-bold leading-tight">{tooltip.lga.lgaName}</span>
            <span className="text-xs font-semibold text-white/65 shrink-0">{tooltip.lga.state}</span>
          </div>
          <p className="text-[13px] leading-snug text-white/90">{tooltip.vec.narrative}</p>
          <div className="flex justify-between items-center pt-1.5">
            <span className="text-white/60">Margin</span>
            <span className="font-bold text-sm tabular-nums">
              {tooltip.vec.shiftPp >= 0 ? "+" : ""}{tooltip.vec.shiftPp.toFixed(1)}%
            </span>
          </div>
        </div>
      )}
    </>
  );
};